cards.push(...expandedCards);
cards.forEach(c=>{
 if(!c.familyCode)c.familyCode=c.id.slice(0,2);
 if(!c.family)c.family=families.find(f=>f[0]===c.familyCode)?.[1]||c.familyCode;
 if(!Array.isArray(c.states)||c.states.length<3)c.states=[
  "Ativo — "+c.essence+" A característica está presente e pode ser observada em atitudes ou circunstâncias concretas.",
  "Latente — "+c.essence+" O tema existe como possibilidade, mas ainda precisa de contexto, tempo ou condições para se manifestar.",
  "Desregulado — "+c.risk+" A expressão desta carta pode perder equilíbrio quando aparece em excesso, deficiência ou sem consideração pelas consequências."
 ];
 if(!Array.isArray(c.relations)||c.relations.length<2){
  const same=cards.filter(other=>other.id!==c.id&&other.archetype===c.archetype&&other.familyCode!==c.familyCode).slice(0,2);
  const pair={Origem:"Expansão",Expansão:"Origem",Equilíbrio:"Integração",Conflito:"Transformação",Bloqueio:"Transformação",Transformação:"Integração",Integração:"Equilíbrio"};
  const complementary=cards.find(other=>other.id!==c.id&&other.archetype===pair[c.archetype]);
  c.relations=[...same.map(other=>"Dialoga com "+other.name+" ("+other.id+"), que compartilha o arquétipo "+c.archetype+" em outra família."),...(complementary?["Pode ser lida em conjunto com "+complementary.name+" ("+complementary.id+"), pelo diálogo entre os arquétipos "+c.archetype+" e "+complementary.archetype+"."]:[])].slice(0,3);
 }
});
const familyGrid=document.getElementById("familyGrid");
familyGrid.innerHTML=families.map((f,i)=>'<button type="button" class="family-card family-'+f[0]+'" data-family="'+f[0]+'" aria-label="Explorar família '+escapeHTML(f[1])+'"><span class="family-topline"><span class="family-code">FAMÍLIA '+f[0]+'</span><span class="family-index">'+String(i+1).padStart(2,"0")+' / 07</span></span><span class="family-glyph">'+f[3]+'</span><span class="family-card-title">'+escapeHTML(f[1])+'</span><span class="family-description">'+escapeHTML(f[2])+'</span><span class="family-count">07 CARTAS <span>↗</span></span></button>').join("");
familyGrid.addEventListener("click",e=>{const card=e.target.closest("[data-family]");if(!card)return;filter.value=card.dataset.family;renderCards();document.getElementById("biblioteca").scrollIntoView({behavior:"smooth"});search.focus({preventScroll:true})});
const cardsGrid=document.getElementById("cardsGrid"),search=document.getElementById("cardSearch"),filter=document.getElementById("familyFilter");
function renderCards(){const q=search.value.toLocaleLowerCase("pt-BR"),f=filter.value;const visible=cards.filter(c=>(f==="all"||c.id.startsWith(f))&&[c.id,c.name,c.archetype,c.word,c.essence,c.symbol,c.family,c.element,c.good,c.risk,c.question,...renderPlanes(c.planes),...(c.states||[]),...(c.relations||[])].join(" ").toLocaleLowerCase("pt-BR").includes(q));cardsGrid.innerHTML=visible.length?visible.map(c=>'<article class="tarot-card" tabindex="0" role="button" data-card="'+c.id+'">'+cardArtwork(c)+'<div class="card-id">'+c.id+' · '+c.archetype.toUpperCase()+'</div><h3>'+c.name+'</h3><p>'+c.word+' · '+c.element+'</p><div class="card-status">VER SIGNIFICADO ↗</div></article>').join(""):'<p>Nenhuma carta encontrada. Tente outro nome, código ou termo.</p>';document.getElementById("libraryFoot").textContent=visible.length+" carta(s) disponível(is) nesta edição. Total integrado: 49."}
search.addEventListener("input",renderCards);filter.addEventListener("change",renderCards);renderCards();
const modal=document.getElementById("cardModal");
function renderPlanes(planes){if(Array.isArray(planes))return planes;return Object.entries(planes||{}).map(([k,v])=>k+" — "+v)}
function openCard(id){
 const c=cards.find(x=>x.id===id);if(!c)return;
 const details=(c.states||[]).map(x=>'<li>'+escapeHTML(x)+'</li>').join("");
 const relations=(c.relations||[]).map(x=>'<li>'+escapeHTML(x)+'</li>').join("");
 document.getElementById("modalContent").innerHTML=cardArtwork(c,true)+'<div class="modal-code">'+c.id+' · '+escapeHTML(c.family||"Existência")+' · ARQUÉTIPO '+escapeHTML(c.archetype.toUpperCase())+'</div><h2>'+escapeHTML(c.name)+'</h2><p><b>Palavra central:</b> '+escapeHTML(c.word)+' · <b>Símbolo:</b> '+escapeHTML(c.symbol)+'</p><h3>Essência</h3><p>'+escapeHTML(c.essence)+'</p><h3>Manifestação nos quatro planos</h3><ul>'+renderPlanes(c.planes).map(x=>'<li>'+escapeHTML(x)+'</li>').join("")+'</ul><h3>Lado construtivo</h3><p>'+escapeHTML(c.good)+'</p><h3>Lado de risco</h3><p>'+escapeHTML(c.risk)+'</p><h3>Estados interpretativos</h3><ul>'+details+'</ul><h3>Relações com outras cartas</h3><ul>'+relations+'</ul><h3>Pergunta de reflexão</h3><p><em>'+escapeHTML(c.question)+'</em></p><div class="notice">Carta simbólica para reflexão. Não é diagnóstico, previsão ou rótulo definitivo.</div>';
 modal.classList.add("open");modal.setAttribute("aria-hidden","false");document.body.style.overflow="hidden";
}
cardsGrid.addEventListener("click",e=>{const el=e.target.closest("[data-card]");if(el)openCard(el.dataset.card)});cardsGrid.addEventListener("keydown",e=>{if((e.key==="Enter"||e.key===" ")&&e.target.dataset.card){e.preventDefault();openCard(e.target.dataset.card)}});function closeModal(){modal.classList.remove("open");modal.setAttribute("aria-hidden","true");document.body.style.overflow=""}document.getElementById("modalClose").addEventListener("click",closeModal);modal.addEventListener("click",e=>{if(e.target.dataset.close)closeModal()});document.addEventListener("keydown",e=>{if(e.key==="Escape")closeModal()});
